entries[470488] = { ["name"] = "Granatenjongleur", ["text"] = "Sofort\nEure 'Lauffeuerbombe' verursacht 5% mehr Schaden und hat eine Chance von 25%, die Abklingzeit von 'Explosivschuss' zurückzusetzen.\n\n'Explosivschuss' verringert die Abklingzeit von 'Lauffeuerbombe' um 2 Sek." }
entries[470489] = { ["name"] = "Tückischer Wurf", ["text"] = "100 Meter Reichweite\nWirken in 1 sek. 1 sek. Abklingzeit\nZerstörung\nDas Wirken von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' gewährt 'Diabolisches Ritual' für 20 Sek.. Wenn 'Diabolisches Ritual' bereits aktiv ist, wird seine Dauer stattdessen um 1 Sek. verringert.\n\nWenn 'Diabolisches Ritual' abläuft, erhaltet Ihr 'Dämonische Kunst', wodurch Euer nächster Einsatz von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' einen Oberanführer, eine Mutter des Chaos oder einen Grubenlord herbeiruft, die einen vernichtenden Angriff gegen Eure Gegner entfesseln.\n\nDämonologie\nDer Verbrauch eines Seelensplitters gewährt Euch für 20 Sek. 'Diabolisches Ritual'. Während 'Diabolisches Ritual' aktiv ist, verringert jeder für einen schadensverursachenden Zauber verbrauchte Seelensplitter dessen Dauer um 1 Sek.\n\nWenn 'Diabolisches Ritual' abläuft, erhaltet Ihr 'Dämonische Kunst', wodurch Euer nächster Einsatz von 'Hand von Gul'dan' einen Oberanführer, eine Mutter des Chaos oder einen Grubenlord herbeiruft, die einen vernichtenden Angriff gegen Eure Gegner entfesseln." }
