entries[470581] = { ["name"] = "Fluss des Waldes", ["text"] = "Wenn 'Freizaubern' verbraucht wird, löst 'Nachwachsen' jetzt auch 'Pflege' mit 60% Effektivität bei einem verletzten Verbündeten in der Nähe aus, wobei jene bevorzugt werden, die mit einem Eurer regelmäßigen Heileffekte belegt sind.\n\nPflege :\nHeilt ein verbündetes Ziel um (446% der Zaubermacht) Gesundheit. Erhält einen 300% Bonus von ' Meisterschaft: Harmonie '." }
