entries[470593] = { ["name"] = "Tod verursachen", ["text"] = "30 Meter Reichweite\nWirken in 3 sek. 3 sek. Abklingzeit\nDer Zaubernde kanalisiert Tod in das Ziel, verursacht 5 Sek. lang alle 1 Sek. Schattenschaden und verringert dessen Bewegungsgeschwindigkeit um 50%." }
entries[470596] = { ["name"] = "Frostfeuerausstoß", ["text"] = "100 Meter Reichweite\nSofort\nFrost\nWenn Ihr 'Kometenhagel' einsetzt, explodiert Euer nächster Einsatz von 'Eislanze' in einem 'Frostfeuerausstoß', der Gegnern in der Nähe (265.6% der Zaubermacht) Frostfeuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n'Frostfeuerausstoß' hat eine Chance von 50%, 'Hirnfrost' zu gewähren.\n\nFeuer\nWenn Ihr 'Meteor' einsetzt, explodiert Euer nächster Einsatz von 'Feuerschlag' in einem 'Frostfeuerausstoß', der Gegnern in der Nähe (265.6% der Zaubermacht) Frostfeuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n'Frostfeuerausstoß' verringert die Abklingzeit von 'Phönixflammen' um 5 Sek." }
entries[470598] = { ["name"] = "Bitte an den Feuerlord", ["text"] = "Sofort\nWenn Dagrans Gesundheit unter 70% fällt, bittet er den Feuerlord um Hilfe und erhält einen Schild, der 38722016 Schaden absorbiert.\n\nEin Avatar von Ragnaros tritt in den Kampf ein und fügt allen Spielercharakteren 3872202 Feuerschaden zu. Der Schaden verringert sich mit der Entfernung zum Einschlagsort." }
entries[470599] = { ["name"] = "Schattenwort: Nekrose", ["text"] = "Wirken in 1 sek. 5 min Abklingzeit\nBelegt einen Spielercharakter mit einer schattenhaften Ansteckung, die die erhaltene Heilung um 90% verringert. Hält er sich 1 Sek. lang im Umkreis von 5 Metern um einen anderen Spielercharakter auf, wird die Ansteckung auf den Spielercharakter in der Nähe übertragen und ein ' Nekrotischer Stoß ' wird freigesetzt." }
