entries[470604] = { ["name"] = "Schattenwort: Nemesis", ["text"] = "200 Meter Reichweite\nSofort\nVerursacht alle 1 Sek. 116166 Schattenschaden, bis Moira besiegt ist. Alle 10 Sek. werden die Stapel von 'Schattenwort: Nemesis' um einen erhöht. Wenn 'Schattenwort: Nemesis' gebannt wird, springt es auf 2 andere Spielercharaktere über." }
entries[470605] = { ["name"] = "Strahlende Infusion", ["text"] = "200 Meter Reichweite\nWirken in 2 sek. 40 sek. Abklingzeit\nMoira kanalisiert einen Strahl aus heiligem Feuer in Dagran, der die beiden 10 Sek. lang alle 0.5 Sek. um 1% Gesundheit heilt. Spielercharaktere, die den Strahl unterbrechen, erleiden alle 0.5 Sek. 'Strahlendes Verbrennen' und verhindern die Heilung." }
