entries[470668] = { ["name"] = "Zwangsinduktion", ["text"] = "Erhöht den Bonus, der gewährt wird, wenn ein Schaden verursachender Finishing-Move einen supergeladenen Combopunkt verbraucht, um 1." }
entries[470669] = { ["name"] = "Widerhallender Tadel", ["text"] = "Gesetzlosigkeit\nNach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von 'Finsterer Stoß' außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden.\n\nMeucheln\nNach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von 'Verstümmeln' außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden.\n\nTäuschung\nNach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von 'Meucheln' außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden." }
entries[470670] = { ["name"] = "Prügelhagel", ["text"] = "Sofort\nPro [(Angriffskraft * 6.25 * (1 + Vielseitigkeit))] Schaden, die Ihr verursacht, wird eine Aufladung von 'Prügelladung' erzeugt. Pro 240 Energie, die Ihr verbraucht, werden alle Aufladungen von 'Prügelladung' entfesselt und verursachen pro Aufladung (60% der Angriffskraft) körperlichen Schaden." }
entries[470671] = { ["name"] = "Widerhallender Tadel", ["text"] = "Sofort\nNach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von [ Düstere Klinge : 'Düstere Klinge' ] [ Täuschung : 'Meucheln' / Gesetzlosigkeit : 'Finsterer Stoß' /\n\nMeucheln\n'Verstümmeln' ] außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden." }
entries[470672] = { ["name"] = "Widerhallender Tadel", ["text"] = "40 Meter Reichweite\nSofort\nBenötigt Einhändige Nahkampfwaffe\nNach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von [ Düstere Klinge : 'Düstere Klinge' ] [ Täuschung : 'Meucheln' / Gesetzlosigkeit : 'Finsterer Stoß' /\n\nMeucheln\n'Verstümmeln' ] außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden." }
entries[470673] = { ["name"] = "Goblingetriebe", ["text"] = "15 Meter Reichweite\nSofort 1.5 min Abklingzeit\nSetzt ein 'Goblingetriebe' ein, das 30 Sek. lang bestehen bleibt und die Kampffähigkeiten von Euch und Euren Verbündeten in der Nähe verbessert. Innerhalb von 10 Metern um das Getriebe ist das Tempo um 15% erhöht." }
entries[470674] = { ["name"] = "Goblinischer Mechanokern", ["text"] = "10 Meter Reichweite\nSofort\nEure Zauber und Fähigkeiten haben eine Chance, jene um Euch zu ermutigen und 107 Vielseitigkeit zu gewähren, die zwischen Euch und Verbündeten in der Nähe aufgeteilt wird.\n\nDie Vielseitigkeit wird für jeden betroffenen Verbündeten erhöht. Bis zu 5 Verbündete." }
