entries[471352] = { ["name"] = "Mehr Saft!", ["text"] = "60 Meter Reichweite\nWirken in 2 sek.\nDer Sprenger der Düsternisverschmolzenen lädt die Gigabombe schnell auf und fügt Spielercharakteren innerhalb von 10 Metern 2515006 Naturschaden zu.\n\nAußerdem erhöht sich der verursachte Schaden des Sprengers der Düsternisverschmolzenen um 10% und die Bewegungsgeschwindigkeit um 10%. Dieser Effekt ist stapelbar." }
