entries[471359] = { ["name"] = "\"Gold\"-Fisch", ["text"] = "5 Meter Reichweite\nSofort\nWährend der Name eine süße Andeutung auf die dicken, goldenen Ablagerungen ist, die durchgehend aus ihren Kiemen treten, ist es auch eine unbequeme Erinnerung an die unregulierte Industrialisierung Lorenhalls.\n\nDieser Fisch ist nun ein nicht wiederzuerkennendes Produkt seiner Umgebung.\n\nBesondere Verwendung:\n\nBlair Barsch\n\nIn einer Bemühung, das makellose Ökosystem von Lorenhall zu bewahren, wäre dieser... \"Fisch\" für Blair Barsch von großem Interesse.\n\nVerbreitungsgebiete:\n\n- Lorenhall\n\nFischschwärme:\n\n- Dampfdruckabfluss\nBeruf:\nAngeln" }
entries[471360] = { ["name"] = "Abschluss der Quest" }
entries[471363] = { ["name"] = "Kopfschuss", ["text"] = "'Tödlicher Schuss' kann jetzt mit 25% Effektivität von 'Präzise Schüsse' profitieren.\n\n'Tödlicher Schuss' verbraucht 'Präzise Schüsse'." }
entries[471365] = { ["name"] = "Lorenhall", ["text"] = "Sofort\nEmpfohlene Fertigkeit: 375\n\nStröme von Dampfdruckabfluss sickern aus den Rohren. Die Gewässer sind nur von den robustesten Khaz-Algar-Fischen und was sonst noch die stinkende Flüssigkeit verträgt, bewohnt.\n\nAngelmöglichkeiten in dieser Zone:\n- Glimmerbecken\n- Energieerfüllter Sekretfleck\n- Dampfdruckabfluss\nBeruf:\nAngeln (225)" }
entries[471366] = { ["name"] = "Dehnbare Bogensehne", ["text"] = "Während 'Volltreffer' aktiv ist, erhöht der Verbrauch von 'Präzise Schüsse' die Dauer von 'Volltreffer' um 1.0 Sek, bis zu 5.0 Sek.\n\n'Volltreffer' erhöht jetzt außerdem die Effektivität von 'Optimierung' um 50%." }
entries[471368] = { ["name"] = "Blairs Goldfischbörse", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nAm Ufer des Zentralen Kanals der Bottichwerke haben Blair Barsch und ihr Trupp von Fischern besonderes Interesse an den örtlichen \"Gold\"-Fischen entwickelt, die in Lorenhall vorkommen.\n\nSchaut vorbei, um an den Erhaltungsbemühungen teilzunehmen und Belohnungen zu verdienen!\nBeruf:\nAngeln (225)" }
