entries[471538] = { ["name"] = "Zeitige Summbiene", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Pünktlich wie eh und je brausen diese Summbienen durch die Zeit, sammeln die fehlgeleiteten Sande der Zeit und bringen sie sicher wieder zu den Zeitwegen zurück.\"\nVerkäufer:\nJeder Zeitwanderungshändler\nKosten:\n5.000" }
entries[471541] = { ["name"] = "Flammender Untergang", ["text"] = "100 Meter Reichweite\nSofort\nBrandwachenzerstörer explodieren in einem Flammenregen, der Spielercharakteren im Bereich 585 Feuerschaden zufügt und Feuerlinge beschwört. Wenn kein Spielercharakter getroffen wird, erleiden alle Spielercharaktere 1170 Feuerschaden." }
entries[471543] = { ["name"] = "Wissen der Zeitwege", ["text"] = "Sofort\nErhöht die durch das Töten von Monstern und das Abschließen von Quests erhaltene Erfahrung um 5%.\n\nDer Abschluss eines Zeitwanderungsdungeons verstärkt den Effekt und setzt die Dauer zurück.\n\nBeim Erreichen von 4 Anwendungen erfolgt eine Umwandlung zu ' Meister der Zeitwege ', was den Effekt auf 30% erhöht." }
