entries[471562] = { ["name"] = "Thrayir, Augen der Sirene", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"In seiner Verzweiflung und Wut beschwor Thrayir einen Sturm, der das Land verwüstete und Cyrces Feinde vernichtete. Nach fast zehntausend Jahren tobt das Meereszornunwetter weiter als Widerhall seiner Macht.\"\nZone:\nSireneninsel" }
